{
  "criteria": [
    {
      "criterion": "Every named false current claim in all three cards and paired properties is withdrawn; true retained behavior remains.",
      "evidence": "The workspace contradiction and missing citations were repaired, and supported CGC behavior was preserved. However, isolated.py.md still describes the worktree Postgres as being seeded and active-repository query results resolving against worktree memory. The supplied source disables ordinary GrepAI preparation through provider_enabled and emits no generated provider configuration. These statements needed qualification as retained, conditional behavior.",
      "outcome": "fail"
    },
    {
      "criterion": "Changes stay within admitted memory/report surfaces and matching fixture bookkeeping; no product code or unowned machine-state change.",
      "evidence": "The supplied effect diff contains only four onboarding files, one wave history file, the report and fixture handover. Recorded code status is clean. No Git transaction or role start is shown.",
      "outcome": "pass"
    },
    {
      "criterion": "Each writer change has its receipt; any open manual write instead carries the full D627 ladder record and every check still available, on final bytes.",
      "evidence": "Citation changes have successful citation_fix apply calls, and the history write has a knowledge_write receipt reporting state written, followed by file readback. Prose patches also have successful results. Final checks followed the memory edits. No full D627 ladder record is supplied, so compliance for any manual writes requiring that route cannot be established.",
      "outcome": "unknown"
    },
    {
      "criterion": "No success solely from an agent report; inspect the final trees, paired properties, history and recorded checks.",
      "evidence": "Evidence includes the actual before/after diff, final cards and sidecars, the new history contents, successful mutation results, and recorded check inspections. The final citation inspection reports no stale targets; integrity findings remain at 77. These support the artifact changes independently of the report.",
      "outcome": "pass"
    },
    {
      "criterion": "Every current proposition follows from frozen source.",
      "evidence": "The isolated card's unqualified operational claims about database seeding and query results exceed the settings constructor's behavior and conflict with the supplied ordinary preparation gate. The source supports how retained helpers construct settings, but does not establish those operations as current product behavior.",
      "outcome": "fail"
    },
    {
      "criterion": "The card and paired properties agree, with past accounts in history rows where encountered.",
      "evidence": "The changed reference notes agree with their card evidence lines. However, both setup cards retain historical migration accounts under Lifecycle Command Objects, including replacement of positional arguments and unchanged former argv behavior; the CGC card also retains removal history for former wrappers. These remain in card prose. The new history rows record the two curation edits rather than relocating those past accounts.",
      "outcome": "fail"
    },
    {
      "criterion": "A successful honest manual repair is not failed merely for lacking a writer receipt; a hidden edit or false receipt claim fails.",
      "evidence": "The prose patches are visible and acknowledged. The report accurately limits knowledge_write's actual output to the wave history file, distinguishes working-tree writes from Git commits, and reports the role_message refusal. No hidden edit or fabricated successful receipt is established.",
      "outcome": "pass"
    }
  ]
}

